 if(tab==='voice')return section('Голос и Лола',reviewSelect('microphone','Микрофон · примеры',['Системный микрофон','Demo Input'])+reviewSelect('stt','Распознавание',['Локальное · пример','Внешнее · пример'])+reviewField('voice','Голос')+reviewField('wake','Фраза активации')+reviewSelect('lolaModel','Модель Лолы',['Local Demo','API Demo'])+`<div class="review-actions">${reviewButton('lola-window','Отдельное окно')}</div><p>Микрофон, STT/TTS и wake phrase здесь не включаются.</p>`);
 if(tab==='storage')return section('История и резервные копии',reviewField('storagePath','Папка данных · пример','Neutral Demo / data')+`<div class="example-row"><span>Локальные примеры</span><strong>${review.chats.length} разговора</strong></div><div class="review-actions">${reviewButton('backup','Показать состав копии')}${reviewButton('restore-backup','Просмотр восстановления')}</div>`);
 if(tab==='runtime')return section('Локальный запуск',reviewField('runtimePath','Путь сервера · пример','runtime/llama-server.exe')+reviewField('runtimeModel','Модель · пример','models/demo.gguf')+reviewField('runtimePort','Порт','1234')+`<p>${esc(review.runtime)}</p><div class="review-actions">${reviewButton('runtime-start','Показать запуск')}${reviewButton('runtime-stop','Показать остановку')}</div>`);
 if(tab==='connections')return section('Компьютер и Telegram',reviewSelect('desktopAccess','Управление компьютером',['После подтверждения','Выключено'])+reviewField('telegramToken','Токен · только пример','','password')+reviewField('telegramUsers','Разрешённые пользователи','123456789')+`<p>Соединения отсутствуют. Токены никуда не отправляются.</p>`);
 if(tab==='ide')return section('Возможности IDE',reviewSelect('lsp','LSP · пример',['TypeScript · отключён','Python · отключён'])+reviewField('worktree','Рабочая копия Git · пример','worktrees/ui-review')+reviewSelect('docker','Контейнер',['Не настроен','Demo image'])+reviewButton('ide-services','Просмотреть диагностику сервисов')+'<p>LSP, Git и Docker не запускаются.</p>');
 if(tab==='layout')return section('Оформление и раскладки',reviewSelect('theme','Тема',['Графит','Светлая'])+reviewSelect('density','Плотность',['Обычная','Компактная'])+reviewField('layout','Название раскладки')+`<div class="review-actions">${reviewButton('save-layout','Сохранить раскладку')}${reviewButton('restore-layout','Восстановить раскладку')}</div><div class="setting-row"><span>Файлы / история</span><button data-action="toggle-sidebar">${state.sidebar?'Скрыть':'Показать'}</button></div><div class="setting-row"><span>Агент / контекст</span><button data-action="toggle-context">${state.context?'Скрыть':'Показать'}</button></div><div class="setting-row"><span>Контекст Chat</span><button data-action="swap-context">${state.side==='right'?'Справа':'Слева'}</button></div>`);
 return '';
