function reviewDialog(){
 const kind=review.dialog;if(!kind)return '';
 let title=review.dialogTitle||'Демонстрация',body='',confirm='';
 if(['rename','project','goto','move','instructions'].includes(kind))body=kind==='move'?`<label class="review-field">Проект<select id="review-dialog-value">${review.projects.map(p=>`<option>${esc(p)}</option>`).join('')}</select></label>`:kind==='instructions'?`<label class="review-field">Инструкции<textarea id="review-dialog-value">${esc(review.dialogValue)}</textarea></label>`:`<label class="review-field">${kind==='goto'?'Номер строки':'Название'}<input id="review-dialog-value" value="${esc(review.dialogValue)}" maxlength="120"></label>`;
 else if(kind==='approval')body=reviewApproval();
 else body=`<p class="review-dialog-description">${esc(review.dialogValue)}</p>`;
 if(kind==='save')body=`<p>src/TaskPanel.tsx · сохранение только в памяти прототипа</p><pre class="review-save-diff">${esc('- '+state.saved.split('\n').slice(-3).join('\n- ')+'\n+ '+state.draft.split('\n').slice(-4).join('\n+ '))}</pre>`;
 if(['rename','project','goto','move','instructions','delete','rollback','dirty','recovery','save'].includes(kind))confirm=reviewButton('dialog-confirm',kind==='delete'?'Удалить пример':kind==='rollback'?'Подтвердить демо-откат':kind==='save'?'Сохранить демо':'Подтвердить','class="review-primary"');
 return `<div class="modal-backdrop review-backdrop"><section class="dialog review-dialog" role="dialog" aria-modal="true" aria-labelledby="review-dialog-title"><header class="dialog-head"><h2 id="review-dialog-title" tabindex="-1">${esc(title)}</h2>${reviewButton('dialog-close',icon('x'),'class="icon-button" aria-label="Закрыть пример"')}</header>${body}<footer class="dialog-foot">${reviewButton('dialog-close',confirm?'Отмена':'Закрыть')}${confirm}</footer></section></div>`;
}
function reviewOpenDialog(kind,title,value=''){review.dialog=kind;review.dialogTitle=title;review.dialogValue=value;review.returnFocus=document.activeElement?.dataset.review||'';render();document.querySelector('#review-dialog-value,#review-dialog-title')?.focus();}
function reviewRichMessage(){return `<div class="review-rich"><h3>План проверки</h3><p>Один запрос — один читаемый блок. Код, ссылки и результаты имеют свою иерархию.</p><ul><li>Сохранить структуру редактора</li><li>Проверить узкое окно</li></ul><pre><code>const status = 'ready';\nconsole.log(status);</code></pre><table><thead><tr><th>Состояние</th><th>Результат</th></tr></thead><tbody><tr><td>Ожидание</td><td>Ввод доступен</td></tr><tr><td>Работа</td><td>Видна остановка</td></tr></tbody></table><p><a href="#review-source" data-review="source-preview">Источник: пример файла</a></p></div>`;}
function reviewAction(id,node){
 const dialogAtStart=review.dialog;
 const chat=review.chats.find(c=>c.id===node?.dataset.chatId);const info=(title,body)=>reviewOpenDialog('info',title,body);
 if(id==='project-menu'){review.menu=review.menu==='projects'?'':'projects';}
 else if(id==='select-project'){review.project=review.projects[Number(node.dataset.projectIndex)];review.menu='';}
 else if(id==='new-project')return reviewOpenDialog('project','Новый демо-проект');
 else if(id==='project-settings')return reviewOpenDialog('instructions','Инструкции проекта',review.criteria);
 else if(id==='new-chat'){const c={id:crypto.randomUUID(),title:'Новый разговор',pinned:false,archived:false};review.chats.unshift(c);state.session=c.title;state.messages=[];state.prompt='';state.scenario='empty';state.emptyHistory=false;review.historyOpen=false;}
 else if(id==='archive'){review.archived=!review.archived;review.menu='';}
 else if(id==='rename-chat'){review.target=chat.id;review.menu='';return reviewOpenDialog('rename','Переименовать разговор',chat.title);}
 else if(id==='pin-chat'){chat.pinned=!chat.pinned;review.menu='';}
 else if(id==='archive-chat'){chat.archived=!chat.archived;review.menu='';}
 else if(id==='fork-chat'){review.chats.unshift({...chat,id:crypto.randomUUID(),title:chat.title+' · ветка',pinned:false,archived:false});review.menu='';}
 else if(id==='move-chat'){review.target=chat.id;review.menu='';return reviewOpenDialog('move','Переместить демо-разговор');}
 else if(id==='export-chat'){review.menu='';return info('Предпросмотр экспорта',`Markdown: # ${chat.title}\n\nВы: Проверь панель задач.\n\nNeutral: Изучу структуру.\n\nJSON: {"title":${JSON.stringify(chat.title)},"messages":2}\n\nФайл не создаётся; это образец состава экспорта.`);}
 else if(id==='delete-chat'){review.target=chat.id;review.menu='';return reviewOpenDialog('delete','Удалить демо-разговор?',chat.title+' · удаляется только локальный пример.');}
 else if(id==='find'){review.findOpen=!review.findOpen;}
 else if(id==='find-next'){const el=document.getElementById('code-input');if(el&&review.find){let at=el.value.toLowerCase().indexOf(review.find.toLowerCase(),el.selectionEnd);if(at<0)at=el.value.toLowerCase().indexOf(review.find.toLowerCase());if(at>=0){el.focus();el.setSelectionRange(at,at+review.find.length);}}return;}
 else if(id==='goto')return reviewOpenDialog('goto','Переход к строке',String(review.line));
 else if(id==='wrap'){review.wrap=!review.wrap;}
 else if(id==='reread')return reviewOpenDialog('dirty','Перечитать демонстрационный файл?',state.draft!==state.saved?'Есть несохранённый черновик. Подтверждение заменит его сохранённым примером.':'Будет повторно показан сохранённый пример; доступа к диску нет.');
 else if(id==='output'){review.output=!review.output;}
 else if(id==='output-log'||id==='output-problems'){review.outputTab=id==='output-log'?'output':'problems';}
 else if(id==='problem-line'){state.selected='TaskPanel.tsx';review.line=4;}
 else if(id.startsWith('search-')){review.searchKind=id.slice(7);}
 else if(id==='cancel-search'){state.projectQuery='';}
 else if(id.startsWith('memory-')){if(state.memory!==review.memorySaved)return info('Сначала сохраните заметку','В примере есть несохранённый черновик. Сохраните его или нажмите «Отменить».');review.memoryTab=id.slice(7);state.memory=review.memoryValues[review.memoryTab];review.memorySaved=state.memory;}
 else if(id==='save-memory'){review.memorySaved=state.memory;review.memoryValues[review.memoryTab]=state.memory;review.memoryRevision++;}
 else if(id==='reset-memory'){state.memory=review.memorySaved;}
 else if(id==='select-run'){review.selectedRun=Number(node.dataset.run);return info('Фоновая задача',review.queue[review.selectedRun]+'\nСостояние и сообщения задачи представлены отдельно. Реальные задачи не запускаются.');}
 else if(id==='cancel-run'){review.queue.splice(Number(node.dataset.run),1);}
 else if(id==='evidence-current'||id==='evidence-stale'){review.evidence=id.slice(9);}
 else if(id==='rollback')return reviewOpenDialog('rollback','Просмотр отката','Демо-снимок 10:24\nsrc/TaskPanel.tsx · изменён\nsrc/styles.css · изменён\n\nПосле подтверждения изменится только состояние примера.');
 else if(id==='recovery-file'){state.selected='TaskPanel.tsx';review.tabs=[...new Set([...review.tabs,state.selected])];state.mode='ide';state.detailsOpen=false;}
 else if(id==='recovery-done'||id==='recovery-notdone'){review.pendingRecovery=id==='recovery-done'?'done':'notdone';return reviewOpenDialog('recovery','Подтвердите результат проверки',id==='recovery-done'?'Вы проверили файл и считаете действие выполненным?':'Вы проверили файл и считаете, что действие не выполнялось?');}
 else if(id==='resume'){state.running=true;state.notice='Демо-задача продолжена после проверки результата.';}
 else if(id==='source-preview'){review.approval='source';review.approvalResult='';return reviewOpenDialog('approval','Просмотр передачи исходников');}
 else if(id==='approval-demo'){review.approval='command';review.approvalResult='';return reviewOpenDialog('approval','Запрос решения');}
 else if(id.startsWith('approval-')){if(['allow','deny','later'].includes(id.slice(9)))review.approvalResult={'approval-allow':'Демо разрешено. Выполнение не производится.','approval-deny':'Демо отклонено. Действие не выполнено.','approval-later':'Решение отложено. Задача ожидает.'}[id];else{review.approval=id.slice(9);review.approvalResult='';}}
 else if(id==='child-result')return info('Результат дочернего исследования','Задача: аудит панели\nДоступ: только чтение\nВывод: убрать историю из файлов и сохранить действия в ленте.\n\nЭто пример краткого результата и связи с родительской задачей.');
 else if(id.startsWith('settings-sub-')){review.settingsSub=id.slice(13);review.formNotice='';}
 else if(id==='save-form'){review.formNotice='Демо-настройки сохранены в памяти. Подключения не изменены.';}
 else if(id==='model-discovery'){review.formNotice='Пример списка: Local Demo, API Demo. Сервер не опрашивался.';}
 else if(id==='model-test'){review.formNotice='Демонстрация: соединение успешно / модель доступна. Запрос не выполнялся.';}
 else if(id==='runtime-start'||id==='runtime-stop'){review.runtime=id==='runtime-start'?'Запущен · демонстрация состояния':'Остановлен · пример';}
 else if(id==='backup')return info('Состав резервной копии','Пример: разговоры · проекты · настройки без ключей · заметки\nФайлы и копии не создаются.');
 else if(id==='restore-backup')return info('Просмотр восстановления','Пример: 3 разговора, 1 проект. Конфликтующие записи будут показаны перед подтверждением. Реальные данные не открываются.');
 else if(id==='ide-services')return info('Диагностика сервисов · пример','LSP: не настроен\nGit worktree: есть незакоммиченные изменения\nDocker: недоступен\n\nЗдесь показываются причина, путь и следующее действие. Реальные сервисы не проверяются.');
 else if(id==='save-layout'){localStorage.setItem('neutral-review-layout',JSON.stringify({name:review.form.layout,layout,sidebar:state.sidebar,context:state.context,side:state.side}));review.formNotice='Демо-раскладка сохранена локально.';}
 else if(id==='restore-layout'){try{const x=JSON.parse(localStorage.getItem('neutral-review-layout'));if(x){layout={...layoutDefaults,...x.layout};state.sidebar=x.sidebar;state.context=x.context;state.side=x.side;review.form.layout=x.name;review.formNotice='Демо-раскладка восстановлена.';}else review.formNotice='Сначала сохраните раскладку.';}catch{review.formNotice='Сохранённая раскладка не читается.';}}
 else if(id==='lola-window'){window.neutralPrototype?.openLola();return;}
 else if(id==='attach'){review.attached=!review.attached;}
 else if(id==='task-options')return reviewOpenDialog('instructions','Критерии текущей задачи',review.criteria);
 else if(id==='copy-message'){const text=node.closest('.message')?.innerText||'';navigator.clipboard.writeText(text).then(()=>{state.notice='Текст примера скопирован.';render();}).catch(()=>info('Копирование недоступно',text));return;}
 else if(id==='latest'){document.querySelector('.message-scroll')?.scrollTo({top:1e7,behavior:'smooth'});return;}
 else if(id==='dialog-close'){const focus=review.returnFocus;review.dialog='';render();(document.querySelector(`[data-review="${focus}"]`)||document.querySelector('#conversation-search,.settings-nav button.selected,.history-toggle'))?.focus();return;}
 else if(id==='dialog-confirm'){
  const value=document.getElementById('review-dialog-value')?.value.trim();if(['rename','project'].includes(review.dialog)&&!value)return;
  if(review.dialog==='rename'){const c=review.chats.find(c=>c.id===review.target);if(state.session===c.title)state.session=value;c.title=value;}
  if(review.dialog==='project'){review.projects.push(value);review.project=value;review.menu='';}
  if(review.dialog==='move'){const c=review.chats.find(c=>c.id===review.target);c.project=value;state.notice='Демо-разговор перемещён в '+value;}
  if(review.dialog==='instructions')review.criteria=value;
  if(review.dialog==='delete')review.chats=review.chats.filter(c=>c.id!==review.target);
  if(review.dialog==='goto')review.line=Math.min(reviewCode().split('\n').length,Math.max(1,Number(value)||1));
  if(review.dialog==='dirty')state.draft=state.saved;
  if(review.dialog==='save'){state.saved=state.draft;state.notice='Демо-черновик сохранён в памяти после просмотра изменений.';}
  if(review.dialog==='rollback')review.snapshot=true;
  if(review.dialog==='recovery')review.recovery=review.pendingRecovery;
  review.dialog='';
 }
 render();
 if(id==='find'&&review.findOpen)document.getElementById('review-find')?.focus();
 if(id==='dialog-confirm'&&dialogAtStart==='goto'){const el=document.getElementById('code-input');if(el){const start=el.value.split('\n').slice(0,review.line-1).join('\n').length+(review.line>1?1:0);el.focus();el.setSelectionRange(start,start);el.scrollTop=(review.line-1)*23;}}
 else if(id==='dialog-confirm')(document.querySelector('#conversation-search,.settings-nav button.selected,.task-drawer header button,#code-input'))?.focus();
}
function reviewBind(){
 if(state.mode==='ide'&&(review.historyOpen||state.detailsOpen))document.querySelector('.agent-panel .conversation')?.setAttribute('inert','');
 document.querySelectorAll('[data-review]').forEach(n=>n.addEventListener('click',e=>{e.preventDefault();reviewAction(n.dataset.review,n);}));
 document.querySelectorAll('[data-chat-menu]').forEach(n=>n.addEventListener('click',()=>{review.menu=review.menu===n.dataset.chatMenu?'':n.dataset.chatMenu;render();document.querySelector(`[data-chat-menu="${n.dataset.chatMenu}"]`)?.focus();}));
 document.querySelectorAll('[data-review-chat]').forEach(n=>n.addEventListener('click',()=>{state.session=review.chats.find(c=>c.id===n.dataset.reviewChat).title;state.scenario='ready';state.messages=[];review.historyOpen=false;review.menu='';render();document.getElementById('prompt')?.focus();}));
 document.querySelectorAll('[data-tab-file]').forEach(n=>n.addEventListener('click',()=>{state.selected=n.dataset.tabFile;render();}));
 document.querySelectorAll('[data-close-file]').forEach(n=>n.addEventListener('click',()=>{if(n.dataset.closeFile==='TaskPanel.tsx'&&state.draft!==state.saved)return reviewOpenDialog('dirty','Несохранённый черновик','Сначала сохраните демо-файл или подтвердите сброс через «Перечитать демо».');review.tabs=review.tabs.filter(f=>f!==n.dataset.closeFile);state.selected=review.tabs.at(-1)||'TaskPanel.tsx';if(!review.tabs.length)review.tabs=[state.selected];render();}));
 document.querySelectorAll('[data-form]').forEach(n=>n.addEventListener('change',()=>{review.form[n.dataset.form]=n.type==='checkbox'?n.checked:n.value;review.formNotice='Есть изменения в демо-форме.';if(['theme','density'].includes(n.dataset.form))render();}));
 document.querySelectorAll('[data-review-field]').forEach(n=>n.addEventListener('input',()=>review[n.dataset.reviewField]=n.value));
 document.getElementById('review-find')?.addEventListener('input',e=>{review.find=e.target.value;document.getElementById('find-count').textContent=reviewFindCount()+' совп.';});
 document.getElementById('memory-note')?.addEventListener('input',e=>{document.getElementById('memory-status').textContent=e.target.value.length+' / 2000 · ревизия '+review.memoryRevision+' · черновик';});
 const code=document.getElementById('code-input');if(code)code.style.whiteSpace=review.wrap?'pre-wrap':'pre';
 document.querySelector('.shell')?.classList.toggle('review-dense',review.form.density==='Компактная');
 document.body.classList.toggle('review-light',review.form.theme==='Светлая');
 document.querySelector('.message-scroll')?.addEventListener('scroll',e=>{document.querySelector('[data-review=latest]')?.classList.toggle('visible',e.target.scrollHeight-e.target.scrollTop-e.target.clientHeight>60);});
}
document.addEventListener('keydown',e=>{
 if(review.dialog){
  if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();reviewAction('dialog-close');return;}
  if(e.key==='Tab'){const nodes=[...document.querySelectorAll('.review-dialog button:not(:disabled),.review-dialog input,.review-dialog select,.review-dialog textarea')];const i=nodes.indexOf(document.activeElement);if(nodes.length&&((e.shiftKey&&i<=0)||(!e.shiftKey&&(i<0||i===nodes.length-1)))){e.preventDefault();(e.shiftKey?nodes.at(-1):nodes[0]).focus();}e.stopImmediatePropagation();}return;
 }
 if(state.settings)return;
 if(e.ctrlKey&&e.key.toLowerCase()==='k'&&state.mode==='ide'){e.preventDefault();e.stopImmediatePropagation();if(!review.historyOpen)action('toggle-history');else document.getElementById('conversation-search')?.focus();return;}
 if(e.ctrlKey&&e.key.toLowerCase()==='f'&&state.mode==='ide'){e.preventDefault();e.stopImmediatePropagation();if(!review.findOpen)reviewAction('find');else document.getElementById('review-find')?.focus();return;}
 if(e.key==='Escape'&&review.menu){e.preventDefault();e.stopImmediatePropagation();review.menu='';render();return;}
 if(e.key==='Escape'&&review.historyOpen){e.preventDefault();e.stopImmediatePropagation();action('toggle-history');}
},true);
